    common={'concept':'pram','rubric':'Distinguere letture e scritture concorrenti; dichiarare le ipotesi.'}
    return [
        dict(common,kind='choice',title='Prima di iniziare',prompt='Due processori leggono contemporaneamente la stessa cella. Nessuno scrive. Qual è il modello meno permissivo che ammette questa operazione?',options=['EREW','CREW','CRCW'],answer='CREW',hints=['Separa il vincolo sulle letture da quello sulle scritture.'],solution='**CREW**: permette letture concorrenti, ma le scritture restano esclusive. EREW vieta anche queste letture; CRCW è più permissivo del necessario.'),
        dict(common,kind='explain',title='Un modello, tre regole',prompt='Una **PRAM** idealizza processori sincroni e memoria condivisa.\n\n| Modello | Letture | Scritture |\n|---|---|---|\n| EREW | Esclusive | Esclusive |\n| CREW | Concorrenti | Esclusive |\n| CRCW | Concorrenti | Concorrenti |\n\nIn CRCW va dichiarata la regola che risolve le scritture concorrenti: common, priority, arbitrary o un’altra regola prevista.\n\nLa **riduzione** produce un unico aggregato. Il **prefix sum inclusivo** produce, per ogni posizione, la somma fino a quella posizione.\n\n*Spiegazione didattica elaborata: confrontala con le fonti collegate.*'),
        dict(common,kind='numeric',concept='reduction',title='Prevedi prima di provare',prompt='Riduzione ad albero di **8 valori**, con almeno **4 processori**. Ogni somma costa un passo; le somme disgiunte dello stesso livello sono simultanee. Quanti passi richiede la riduzione? Non contare il caricamento dei dati.',answer=3,hints=['Al primo livello: 4 somme; poi 2; infine 1.'],solution='**3 passi**, cioè $\\log_2 8$. Le somme totali sono $4+2+1=7$: tempo parallelo e lavoro totale sono quantità diverse.'),
        dict(common,kind='html',concept='reduction',title='Laboratorio · riduzione e scan',prompt='Prova un caso, cambia processori o algoritmo e confronta il risultato con la tua previsione. Il simulatore conta operazioni ideali, non misura l’hardware.',html=(Path(__file__).resolve().parent.parent/'studio/public/pram.html').read_text(),fallback='Riduzione [1,2,3,4,5,6,7,8]: 4 somme al primo livello, 2 al secondo, 1 al terzo. Totale 36, lavoro 7, profondità 3. Prefix sum inclusivo: [1,3,6,10,15,21,28,36].'),
        dict(common,kind='completion',concept='scan',title='Ricostruisci il passo',prompt='Scan inclusivo Hillis–Steele con doppio buffer. Completa la sola espressione del ramo $i\\ge d$:\n\n```text\nnext[i] = ____\n```\n\nIl buffer `old` resta invariato durante il livello. Usa `old`, `i` e `d`.',answer='old[i]+old[i-d]',hints=['Somma il prefisso corrente con quello distante d posizioni.'],solution='`old[i] + old[i-d]`. Per `i < d`, copia `old[i]`. Dopo il livello si scambiano i buffer e si raddoppia `d`.'),
        dict(common,kind='open',title='Applica · domanda autentica',prompt='What is the difference between EREW, CREW, and CRCW models? Provide an example for each of them.',authentic=True,rubric='Criteri proposti: letture/scritture corrette per ciascun modello, esempi coerenti, regola CRCW esplicita quando necessaria.',solution='EREW: accessi esclusivi, ad esempio copie verso celle distinte con letture distinte. CREW: broadcast di una cella a destinazioni distinte. CRCW: più processori scrivono nella stessa cella secondo una regola dichiarata; nel modello common devono scrivere lo stesso valore.'),
        dict(common,kind='numeric',concept='reduction',title='Una variante senza aiuti',prompt='Riduci **16 valori** con **2 processori**, usando lo stesso albero binario. Ogni processore esegue una somma per passo. I livelli non si sovrappongono. Quanti passi servono? Scrivi il totale.',answer=8,hints=['I livelli richiedono rispettivamente 8, 4, 2 e 1 somme. Con 2 processori, arrotonda in alto il tempo di ogni livello.'],solution='$\\lceil8/2\\rceil+\\lceil4/2\\rceil+\\lceil2/2\\rceil+\\lceil1/2\\rceil=4+2+1+1=8$ passi.'),
        dict(common,kind='explain',title='Conserva quello che hai imparato',prompt='Il percorso è concluso. I richiami brevi verificati sono stati programmati. Torna alla scheda **Ripassi** quando sono dovuti.\n\nPer la verifica a distanza useremo problemi diversi: ricordare la risposta di oggi non basta. Puoi ora chiedere un altro argomento oppure avviare una simulazione autonoma.'),
    ]
